SELECT p.id, p.full_name, p.first_name, p.last_name, p.is_active, p.is_incumbent, p.source,
       g.name AS government, c.name AS chamber, o.title, d.label AS district
  FROM essentials.politicians p
  LEFT JOIN essentials.office_current_holder och ON och.politician_id = p.id
  LEFT JOIN essentials.offices o ON o.id = och.office_id
  LEFT JOIN essentials.chambers c ON c.id = o.chamber_id
  LEFT JOIN essentials.governments g ON g.id = c.government_id
  LEFT JOIN essentials.districts d ON d.id = o.district_id
 WHERE p.is_active
   AND (lower(btrim(p.last_name)), lower(btrim(p.first_name))) IN (('woodward','james'),('hart','phil'),('okuniewicz','doug'),('toews','ben'),('bjerke','carl'),('foreman','daniel'),('carlson','cindy'),('zito','christy'),('shippy','brandon'),('nichols','tammy'),('blaylock','camille'),('adams','ben'),('lenney','brian'),('grow','c.'),('galloway','codi'),('rabe','alison'),('semmelroth','carrie'),('ward-engelking','janie'),('wintrow','melissa'),('keyser','josh'),('bernt','treg'),('den hartog','lori'),('lakey','todd'),('zuiderveld','glenneda'),('kohl','joshua'),('taylor','ron'),('anthon','kelly'),('guthrie','jim'),('ruchti','james'),('vanorden','julie'),('burtenshaw','van'),('cook','kevin'),('lent','dave'),('ricks','doug'),('harris','mark'),('sauter','mark'),('rasor','cornel'),('scott','heather'),('hawkins','dale'),('barbieri','vito'),('redman','jordan'),('alfieri','joe'),('price','elaine'),('mendive','ron'),('wisniewski','tony'),('mccann','lori'),('mitchell','brandon'),('harris','kyle'),('shepherd','charlie'),('beiswenger','robert'),('thompson','faye'),('shirts','john'),('boyle','judy'),('moyle','mike'),('skaug','bruce'),('marmon','kent'),('cayler','lucas'),('cornilles','jeff'),('crane','jaron'),('crane','brent'),('tanner','steven'),('hill','ted'),('tanner','josh'),('berch','steve'),('healey','dori'),('galaviz','soñia'),('haws','anne'),('gannon','john'),('egbert','megan'),('rubel','ilana'),('green','brooke'),('church','monica'),('mathias','chris'),('palmer','joe'),('holtzclaw','james'),('petzke','james'),('ehlers','jeff'),('vander woude','john'),('monks','jason'),('bruce','chris'),('dygert','shawn'),('hostetler','clint'),('miller','steve'),('hall','don'),('leavitt','david'),('pohanka','mike'),('nelsen','jack'),('pickett','douglas'),('handy','clay'),('cheatum','richard'),('garner','dan'),('manwaring','dustin'),('burgoyne','tanya'),('cannon','david'),('fuhriman','ben'),('raymond','jerald'),('furniss','rod'),('mickelsen','stephanie'),('bingham','erin'),('ehardt','barbara'),('erickson','marco'),('weber','jon'),('raybould','britt'),('veile','michael'),('wheeler','josh'))
 ORDER BY p.last_name, p.first_name;